export const isPiece = k => k in PIECES;

const memo = {};
export function depth(k) {
  if (k in memo) return memo[k];
  const r = KANJI[k]?.recipes;
  return (memo[k] = r ? 1 + Math.max(...r[0].map(depth)) : 0);
}
export const kLevel = k => Math.min(5, depth(k) + 1);
// Grado: el tipo de kanji según su composición (fijo, 1–5). No confundir con el Nivel (Nv), que sube con EXP hasta MAX_LV.
export const GRADES = [
  { n: 'Fundamental', d: 'Componentes fundamentales' },
  { n: 'Compuesto', d: 'Primera composición' },
  { n: 'Intermedio', d: 'Composición intermedia' },
  { n: 'Complejo', d: 'Composición compleja' },
  { n: 'Avanzado', d: 'Composición avanzada' },
];
export const gradeTag = (k, mode = 'full') => { const L = kLevel(k), G = GRADES[L - 1];
  return `<span class="grade g${L} ${mode}" title="Grado ${L} · ${G.d}"><i>${L}</i>${mode === 'gem' ? '' : mode === 'short' ? `Grado ${L}` : `Grado ${L} · ${G.n}`}</span>`; };
// Espacios que ocupa una criatura: crecen con su nivel KANJŪ
export const size = k => kLevel(k);

export function element(k) {
  const d = KANJI[k];
  return d.el || element(d.recipes[0].find(p => !isPiece(p)));
}
export function roots(k) {
  if (isPiece(k)) return [];
  const r = KANJI[k].recipes;
  return r ? r[0].flatMap(roots) : [k];
}
export function evolutionsOf(k) {
  return Object.keys(KANJI).filter(c => KANJI[c].recipes?.some(r => r.includes(k)));
}
// Balance validado con simulación de 30 días (ver docs/ECONOMIA.md)
export const evoLevel = c => 5 + (depth(c) - 1) * 3;
// Maestría mínima de los componentes para evolucionar o fusionar: obliga a repasar en días distintos
export const learnGate = c => depth(c) <= 1 ? 2 : depth(c) + 2;
export const MAX_LV = 15;
const _all = k => [...KANJI[k].on, ...KANJI[k].kun];
export const mainRead = k => _all(k).includes(MAIN_READ[k]) ? MAIN_READ[k] : _all(k)[0];
// Todas las lecturas, con la principal primero (reads(k)[0] es siempre la principal)
export const reads = k => { const m = mainRead(k); return m ? [m, ..._all(k).filter(r => r !== m)] : []; };
export const plain = r => r.replace(/[()]/g, '');

// --- Tipos 五行 (gogyō): los cinco elementos japoneses tradicionales ---
// Ciclo de dominio (相剋 sōkoku): 木 vence a 土, 土 a 水, 水 a 火, 火 a 金, 金 a 木.
export const TYPES = {
  wood: { k: '木', name: 'Madera', yomi: 'もく', col: '#4fbf6a', beats: 'earth' },
  fire: { k: '火', name: 'Fuego', yomi: 'か', col: '#e8503a', beats: 'metal' },
  earth: { k: '土', name: 'Tierra', yomi: 'ど', col: '#c78f12', beats: 'water' },
  metal: { k: '金', name: 'Metal', yomi: 'きん', col: '#8a9bb0', beats: 'wood' },
  water: { k: '水', name: 'Agua', yomi: 'すい', col: '#2f93b8', beats: 'fire' },
};
const EL_TYPE = { wood: 'wood', life: 'wood', thread: 'wood', fire: 'fire', sun: 'fire', heart: 'fire', earth: 'earth', person: 'earth', void: 'earth',
  metal: 'metal', power: 'metal', voice: 'metal', water: 'water', moon: 'water', sky: 'water', eye: 'water', spirit: 'water' };
export const typeOf = k => EL_TYPE[element(k)];
export const typeMult = (a, d) => TYPES[a].beats === d ? 1.5 : TYPES[d].beats === a ? .7 : 1;

// --- Familias 族: kanji que comparten una pieza o un kanji base (mínimo 3) ---
export const FAMILIES = (() => {
  const by = {};
  for (const [k, K] of Object.entries(KANJI)) for (const p of new Set((K.recipes || []).flat())) (by[p] ??= new Set()).add(k);
  return Object.entries(by).filter(([, s]) => s.size >= 3).map(([root, s]) => ({ root, members: [...s] })).sort((a, b) => a.members.length - b.members.length);
})();
